#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

banner "GiveMeSub: Mac App Store setup"

stage "Before you start"
say "Builds and uploads go through Xcode Cloud with cloud signing, so no certificates,"
say "profiles, API keys or GitHub secrets are needed."
say "You need the Apple Developer Account Holder login."
say "KIR-382 must be merged first: sandboxed build verified, app icon,"
say "LSApplicationCategoryType, ITSAppUsesNonExemptEncryption, privacy link."
confirm "Is KIR-382 merged?" || { warn "Merge KIR-382 first, then re-run."; exit 1; }

stage "Free Apps agreement"
open_url "https://appstoreconnect.apple.com/business"
step "Look for the Free Apps agreement. If it is not Active, review and accept it."
pause "Agreement Active? Press Enter."

stage "App ID"
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "Look for com.kirhgoff.givemesub in the list. If it exists, skip the rest."
step "Otherwise: + > App IDs > App > Continue."
step "Description: GiveMeSub. Explicit Bundle ID: com.kirhgoff.givemesub. No capabilities needed."
step "Continue > Register."
pause "App ID exists? Press Enter."

stage "App record"
open_url "https://appstoreconnect.apple.com/apps"
step "+ > New App."
step "Platform: macOS. Name: GiveMeSub (if taken, try \"GiveMeSub – Live Captions\")."
step "Primary language: English (U.S.). Bundle ID: com.kirhgoff.givemesub (team 4R5Q3BHK2N)."
step "SKU: givemesub. User Access: Full Access. Create."
step "Open the app > App Information > General Information, look for the Apple ID (a number)."
ask ASC_APP_ID "Paste the Apple ID (numeric):"
write_env ASC_APP_ID "$ASC_APP_ID"

stage "Privacy policy URL"
say "The policy must state: audio is processed on-device, nothing is stored or sent,"
say "no analytics, and a contact. KIR-382 adds PRIVACY.md to the repo."
DEFAULT_PRIVACY_URL="https://github.com/kirhgoff/give-me-sub/blob/main/PRIVACY.md"
note "Suggested: $DEFAULT_PRIVACY_URL"
ask PRIVACY_POLICY_URL "Privacy policy URL (Enter for suggested unless a current value is kept):"
PRIVACY_POLICY_URL="${PRIVACY_POLICY_URL:-$DEFAULT_PRIVACY_URL}"
write_env PRIVACY_POLICY_URL "$PRIVACY_POLICY_URL"
step "In App Store Connect: App Information > Privacy Policy URL > paste it above > Save."
pause "Saved? Press Enter."

stage "App Privacy label"
open_url "https://appstoreconnect.apple.com/apps/$ASC_APP_ID/distribution/privacy"
step "Get Started."
step "Choose \"No, we do not collect data from this app\"."
step "Save, then Publish."
pause "Published? Press Enter."

stage "Xcode Cloud workflow"
say "Open GiveMeSub.xcodeproj in Xcode. The existing PR workflow stays as is."
step "Report navigator (⌘9) > Cloud tab > Manage Workflows > +."
step "Name: App Store. Start condition: Tag Changes, matching v*."
step "Environment: Xcode 27, macOS 26."
step "Action: Archive – macOS, scheme GiveMeSub, Deployment Preparation: App Store Connect."
step "Post-action: TestFlight Internal Testing."
say "After the next v* tag, the build appears in App Store Connect > TestFlight within ~30 min."
pause "Workflow saved? Press Enter."

stage "Screenshots"
say "1-10 PNG or JPEG, 16:10, no alpha. 2880x1800 (or 2560x1600, 1440x900, 1280x800)."
say "Show: the overlay captioning a video, the menu, Settings."
step "Capture with ⌘⇧5 on a full-screen window, then fix size and strip alpha:"
note "sips -z 1800 2880 shot.png --out shot-store.png"
note "sips -s format jpeg shot-store.png --out shot-store.jpg"
pause "Screenshots ready? Press Enter."

stage "Listing and submit"
open_url "https://appstoreconnect.apple.com/apps/$ASC_APP_ID/distribution"
say "Paste these fields:"
note "Subtitle: Live captions for any audio"
note "Keywords: captions,subtitles,transcribe,live,speech,accessibility,deaf,hearing,video,audio"
note "Support URL: https://github.com/kirhgoff/give-me-sub"
say "Description:"
note "GiveMeSub shows live captions for whatever your Mac plays. Videos, calls, podcasts,"
note "streams: the words appear in a floating overlay above every window, fullscreen apps included."
note ""
note "Everything stays private. Speech is transcribed on your Mac by a bundled model."
note "Audio is never stored or sent anywhere, and there are no accounts or analytics."
note ""
note "Toggle captions from anywhere with ⌃⌥⌘C, the menu bar, or Shortcuts. Settings lets you"
note "choose the language, caption font, size, colour and background, and Rolling or Subtitles mode."
say "Review Notes:"
note "Play any video with speech (e.g. YouTube), click the menu bar icon > Start captions,"
note "and allow System Audio Recording. Captions appear in a floating overlay."
note "All audio is transcribed on-device by a bundled model, never stored or transmitted."
note "The filled menu bar icon shows while capturing. ⌃⌥⌘C toggles captions;"
note "givemesub://toggle and the Shortcuts actions do the same. No account needed."
say "Then:"
step "Add the screenshots."
step "App Information: Category Utilities. Age Rating questionnaire: answer None to all."
step "Pricing and Availability: Free."
step "Build: select the TestFlight build from stage 7."
note "No build listed yet? Push a v* tag (it also publishes the brew release), wait for TestFlight, then come back."
step "Add for Review."
confirm "Everything filled in and ready to press Submit for Review?" || warn "Submit later from the app version page."

finish
note "Next releases: push a v* tag, then in App Store Connect create the new version, pick the build and submit."
